def max_herb_value(T: int, M: int, herbs: list[tuple[int, int]]) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.
    This is a 0/1 knapsack problem where the time is the capacity constraint.
    """
    if T < 0 or M < 0:
        raise ValueError("T and M must be non‑negative")
    if len(herbs) != M:
        raise ValueError("Length of herbs list must equal M")
    if T == 0 or not herbs:
        return 0

    # Initialize DP array where dp[t] is the maximum value achievable with total time t
    dp: list[int] = [0] * (T + 1)

    for time_cost, value in herbs:
        if time_cost < 0 or value < 0:
            # Skip invalid herb entries
            continue
        if time_cost > T:
            # Cannot pick this herb due to time constraint
            continue
        # 0/1 knapsack: iterate backwards to avoid reuse
        for t in range(T, time_cost - 1, -1):
            new_val = dp[t - time_cost] + value
            if new_val > dp[t]:
                dp[t] = new_val

    return max(dp)

